            if (fabricData.status === 'success' && fabricData.data) {
                const fabric = fabricData.data;

                // Format the fabric details into grouped cards
                let html = `
                    <div class="row g-4">
                        <!-- Basic Information Card -->
                        <div class="col-lg-6">
                            <div class="card shadow-sm">
